// Posting a typed GraphQL document (generated by `pnpm codegen` into src/gql) with fetch. One query per page and
// no client-side cache to manage, so no GraphQL client library.
import { API_URL } from "./api";
import type { TypedDocumentString } from "@/gql/graphql";

export async function gql<Result, Variables>(document: TypedDocumentString<Result, Variables>, variables: Variables): Promise<Result> {
  const response = await fetch(`${API_URL}/graphql`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ query: document.toString(), variables }),
    cache: "no-store",
  });
  const body = (await response.json()) as { data?: Result; errors?: { message: string }[] };
  if (!response.ok || body.errors?.length || !body.data) {
    throw new Error(`GraphQL ${response.status}: ${body.errors?.map((e) => e.message).join("; ") ?? "no data"}`);
  }
  return body.data;
}
